def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[-1][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]
    coop_rate = opp_c / n

    # Endgame exploitation only against clearly cooperative opponents.
    if n >= 96:
        if coop_rate >= 0.75 or (opp_d <= 2 and n >= 90):
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Count recent defections.
    w = 6 if n >= 6 else n
    recent_opp_d = 0
    for i in range(n - w, n):
        if opp[i] == 'D':
            recent_opp_d += 1

    # Sustained defection: stop feeding it.
    if recent_opp_d >= 5:
        return 'D'
    if coop_rate <= 0.25:
        return 'D'
    if coop_rate <= 0.4:
        if last_opp == 'D' or recent_opp_d >= 3:
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Very cooperative opponent: reciprocate, with rare probes.
    if coop_rate >= 0.9:
        if n < 90 and my_d < 4 and n % 17 == 0:
            return 'D'
        return 'C'

    # Strongly cooperative: cooperate, but retaliate on recent defections.
    if coop_rate >= 0.7:
        if recent_opp_d >= 3:
            return 'D'
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        if last_opp == 'C':
            return 'C'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Moderate: tit-for-tat with forgiveness, but avoid being exploited.
    if last_opp == 'D':
        if recent_opp_d >= 3:
            return 'D'
        if last_me == 'D':
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        # We cooperated, they defected: punish but allow recovery.
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated.
    if last_me == 'D':
        if recent_opp_d <= 1:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'
    if recent_opp_d >= 2:
        if rng.random() < 0.4:
            return 'D'
    return 'C'
